def file_name_check(file_name):
    def check_digits(file_name):
        return sum(c.isdigit() for c in file_name) <= 3

    def check_dot(file_name):
        return file_name.count('.') == 1

    def check_start_letter(file_name):
        return file_name.split('.')[0].isalpha()

    def check_extension(file_name):
        valid_extensions = ['txt', 'exe', 'dll']
        return file_name.split('.')[-1] in valid_extensions

    if check_digits(file_name) and check_dot(file_name) and check_start_letter(file_name) and check_extension(file_name):
        return 'Yes'
    else:
        return 'No'
